-- ds_run_errors — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_run_errors.
-- Every check that errored on the latest scheduled run, with the warehouse's message. Pipeline: Errors on the latest run.

SELECT k.run_ts, k.rule_id, k.target_table, k.severity, k.business_domain, k.message
FROM   sdpt_data_trnf.udp_brnz.dq_results_check_run k
WHERE  k.run_id = (SELECT run_id FROM sdpt_data_trnf.udp_brnz.dq_results_v_scheduled_run WHERE is_latest) AND k.status = 'error'
